import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load brushed metal texture via cached loader
  const metalMap = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(metalMap, uv());

  // Create plane geometry
  // Aspect ratio derived from atlas region (512x320)
  const aspectRatio = 512 / 320;
  const height = 1.25;
  const width = height * aspectRatio;

  const geometry = new THREE.PlaneGeometry(width, height);

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position and transformation from config
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ = [0, 0, 0], scaleXYZ = [1, 1, 1] } = config.scenePosition;
    mesh.position.set(x, y, z);
    mesh.rotation.set(...rotationXYZ);
    mesh.scale.set(...scaleXYZ);
  }

  group.add(mesh);

  // Cleanup function to dispose resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalMap.dispose();
  };

  // Event handlers (empty for static card)
  group.userData.handlers = {};

  return group;
}
